// Map: keys of ANY type, insertion order, direct size
const visits = new Map();
visits.set('sara', 3);
visits.set(42, 'answer');
visits.set({ id: 1 }, 'object keys work');
console.log(visits.get('sara'), visits.size); // 3 3
console.log(visits.has(42));                  // true
visits.delete(42);
for (const [key, value] of visits) console.log(key, value);

// Convert between objects and Maps
const obj = { a: 1, b: 2 };
const m = new Map(Object.entries(obj));       // obj -> Map
const back = Object.fromEntries(m);           // Map -> obj

// Set: unique values, O(1) add/has/delete
const ids = new Set([1, 2, 2, 3]);
console.log(ids.size);                        // 3
ids.add(3).add(4);
console.log([...ids]);                        // [1, 2, 3, 4]

const uniq = arr => [...new Set(arr)];
console.log(uniq(['a', 'b', 'a']));           // ['a', 'b']

const setA = new Set([1, 2, 3]);
const common = [1, 2, 3].filter(x => new Set([2, 3, 4]).has(x)); // intersection [2, 3]
```
Use `Map` when keys are not strings, when you add/delete keys frequently, need `size`, or iterate in insertion order. Use `Set` for deduplication and membership tests — much cleaner than `arr.indexOf(x) !== -1`. Object keys are always strings/symbols; Map keys keep their type (even objects and NaN).

